INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0.2, 0, "", 0, 1, 112, 3, 106011, "wac_215_talk_arm_crossed_loop", 112017, "wac_215_talk_arm_crossed");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 112, 21, "vo_wac_220215", 0, 112018, "vo_wac_220215_003");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 112, 11, 106011, 1, 112019, "重要な依頼？\nまた面倒くさいこと押し付けようと\nしてんじゃないでしょうね……");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 112, 91, 112019, "", 112020, "");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0.2, 1, "", "", "", 112, 3, 106011, "", 112021, "wac_215_idle_arm_crossed");
