INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 112, 21, "vo_wac_220215", 0, 112028, "vo_wac_220215_005");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 112, 11, 106431, 1, 112029, "ランドソルを囲む壁に絵を？\nふぅん、楽しそうね。\nここに描けばいいのかしら？");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 112, 91, 112029, "", 112030, "");
