INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 8012, 21, "vo_wac_220505", 0, 8012025, "vo_wac_220505_000");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 8012, 11, 104411, 1, 8012026, "ふふ。壮観じゃ。世界征服が進んでいる\nようで心が踊るのう……\nそうじゃ！　このまま我らの絵で\n壁を埋め尽くすのはどうじゃ？");
