INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 14312, 21, "vo_wac_220707", 0, 14312026, "vo_wac_220707_001");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 14312, 11, 104311, 1, 14312027, "バ、バカ！　絵筆持ったまま\n踊るなって！　尻尾に\n絵の具がつくと落とすの大変なんだよ！");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 14312, 91, 0, "", 14312028, "");
