INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0.2, 0, "", "", 1, 16412, 3, 100811, "wac_talk_wish_loop", 16412033, "wac_talk_wish_in");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 16412, 21, "vo_wac_220728", 0, 16412034, "vo_wac_220728_002");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 16412, 11, 100811, 1, 16412035, "絵の下書きはボクに任せて。\nすべての美しさの源になる存在……\nそれがボクだからね！");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 16412, 91, 0, "", 16412036, "");
