INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 16412, 21, "vo_wac_220728", 0, 16412044, "vo_wac_220728_004");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 16412, 11, 105511, 1, 16412045, "あっ、道具のお片づけは\n私がしておきました……\nこういう地味な作業でも、\nお役に立ててるといいんですけど……");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 16412, 91, 0, "", 16412046, "");
