INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 16412, 21, "vo_wac_220728", 0, 16412049, "vo_wac_220728_005");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 16412, 11, 105311, 1, 16412050, "うむ！　完璧なコンビネーションだ！\n過去一番の団結と言っても過言ではないな！\n……それはそれでちょっと複雑だが。\nこの調子でお絵描き事業を完遂するぞ！");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 16412, 91, 0, "", 16412051, "");
