INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0.2, 1, "", "", "", 16612, 3, 105111, "", 16612039, "wac_talk_surprise_loop_shy");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 16612, 21, "vo_wac_220730", 0, 16612040, "vo_wac_220730_003");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 16612, 11, 105111, 1, 16612041, "まったくもう……\nみんなして絵の具まみれじゃない。\nって、あら？　この赤いのは……");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 16612, 91, 0, "", 16612042, "");
