INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0.2, 1, "", "", 1, 17812, 3, 103711, "", 17812024, "wac_idle_arm_crossed");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0.2, 0, "", "", 1, 17812, 3, 104711, "wac_talk_sad_loop_L", 17812025, "wac_talk_sad_in_L");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 17812, 21, "vo_wac_220811", 0, 17812026, "vo_wac_220811_001");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 17812, 11, 104711, 1, 17812027, "トモちゃんは真面目だね。\n私は絵の具が鎧にはねたら\nどうしようって、そればかり\n考えていたよ。");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 17812, 91, 0, "", 17812028, "");
