INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0.2, 0, "", "", 1, 17812, 3, 107111, "wac_talk_doya_loop_L", 17812035, "wac_talk_doya_in_L");
