INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 21312, 21, "vo_wac_220915", 0, 21312022, "vo_wac_220915_001");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 21312, 11, 110811, 1, 21312023, "あァ、国家そういうトコあんだよ。\nうちも前に世界救う的なバイトしたけど\nあいつあんときの日給まだくんないわ。");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 21312, 91, 0, "", 21312024, "");
