INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 23812, 21, "vo_wac_221010", 0, 23812040, "vo_wac_221010_003");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 23812, 11, 105511, 1, 23812041, "絶対に違うと思います……\n二人とも、自分の好きなものに\n忠実なだけというか……");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 23812, 91, 0, "", 23812042, "");
