INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0.2, 0, "", "", 1, 25212, 3, 106811, "wac_talk_arm_crossed_loop_L", 25212026, "wac_talk_arm_crossed_in_L");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 25212, 21, "vo_wac_221024", 0, 25212027, "vo_wac_221024_002");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 25212, 11, 106811, 1, 25212028, "それを言うなら文武両道、\nだねリノちゃん\nでもまあ、マスターとして\nアタシも鼻が高いよ。……なんてね。");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 25212, 91, 0, "", 25212029, "");
