INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0.2, 0, "", "", 1, 25212, 3, 104911, "wac_talk_smile_loop", 25212031, "wac_talk_smile_in");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 25212, 21, "vo_wac_221024", 0, 25212032, "vo_wac_221024_003");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 25212, 11, 104911, 1, 25212033, "も～、二人とも。\n褒めても弟くん以外には\n何もでないよ～？");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 25212, 91, 0, "", 25212034, "");
