INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 26212, 21, "vo_wac_221103", 0, 26212021, "vo_wac_221103_000");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 26212, 11, 103811, 1, 26212022, "ふぅ……これで完成、です。\n前よりも上手に描けたでしょうか？\nやっぱり絵を描くのって楽しいですね。");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 26212, 91, 0, "", 26212023, "");
