INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 26232, 21, "vo_wac_221103", 0, 26232022, "vo_wac_221103_201");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 26232, 11, 109211, 1, 26232023, "そんなことない！　バッチリだよ！\nやっぱりグレアは天才かも！\nアートの申し子で間違いない！\nルゥもそう思うでしょ！");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 26232, 91, 0, "", 26232024, "");
