INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 28412, 21, "vo_wac_221125", 0, 28412041, "vo_wac_221125_004");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 28412, 11, 100511, 1, 28412042, "ジュンさん、それにみんなも、\n手伝ってくれてありがとうッス！\nおかげで、ワイルドなかっこいい絵に\n仕上がったッスよ♪");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 28412, 91, 0, "", 28412043, "");
