INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 34312, 21, "vo_wac_230123", 0, 34312025, "vo_wac_230123_000");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 34312, 11, 100711, 1, 34312026, "できたの～！\n今回もよく描けたから、\n当然の権利としてプリンを\n要求するの、早く出せなの。");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 34312, 91, 0, "", 34312027, "");
