INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 34312, 21, "vo_wac_230123", 0, 34312030, "vo_wac_230123_001");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 34312, 11, 103111, 1, 34312031, "……困りましたね。\n今日はもうミヤコさんに渡せるプリンが\nありませんが、どうしましょう？");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 34312, 91, 0, "", 34312032, "");
