INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0.2, 0, "", "", 1, 38012, 3, 104811, "wac_talk_sad_loop_surprise_L", 38012025, "wac_talk_sad_in_surprise_L");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 38012, 21, "vo_wac_230301", 0, 38012026, "vo_wac_230301_001");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 38012, 11, 104811, 1, 38012027, "商売って……描いた絵を売るとか？\nうーん、別に芸術家として\n有名になったわけでもないし、\nちょっと難しいような……");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 38012, 91, 0, "", 38012028, "");
