INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", 0, "", "", "", 38012, 21, "vo_wac_230301", 0, 38012031, "vo_wac_230301_002");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES (0, 10, 0.5, 0, 1, 38012, 11, 103411, 1, 38012032, "麦しゅわ！　麦しゅわの絵を描くの！\nそれをね～、酒場とかに売って～……\nそのお金で、麦しゅわを買うの～♪\n……ひっく。");
INSERT INTO `v1_221d7ecf3e07681f3d95cc62577dfa7345d5bf18946c96de27469636e0a07c97` VALUES ("", "", "", "", "", 38012, 91, 0, "", 38012033, "");
